 app.patch('/'+table+'/:id',async req=>{const a=await actor(req,table,true);const id=(req.params as {id:string}).id;const r=await getScoped(table,id,a);if(!staff(a)&&table!=='tickets'&&table!=='conversations')fail(403,'Administrative access required.');const b=z.record(z.string(),z.unknown()).parse(req.body);const patchSchema=(spec.create as z.ZodObject).partial();const parsed=patchSchema.parse(b) as Record<string,unknown>;const clean=Object.fromEntries(Object.keys(b).filter(k=>Object.hasOwn(parsed,k)).map(k=>[k,parsed[k]]));const keys=Object.keys(clean).filter(k=>spec.columns.includes(k));if(keys.length!==Object.keys(b).length)fail(400,'One or more fields cannot be changed.');if(!staff(a)&&keys.some(k=>!['title','body','status'].includes(k)))fail(403,'This field requires administrative access.');if(clean.assignee_id){const [member]=await q('SELECT 1 FROM memberships WHERE user_id=$1 AND org_id=$2',[clean.assignee_id,r.org_id]);const [team]=await q('SELECT 1 FROM users WHERE id=$1 AND global_role IS NOT NULL',[clean.assignee_id]);if(!member&&!team)fail(400,'Assignee is not in this workspace.')}if(table==='tasks'&&clean.status==='done'){const pending=await q("SELECT 1 FROM task_dependencies d JOIN tasks t ON t.id=d.depends_on WHERE d.task_id=$1 AND t.status<>'done'",[id]);if(pending.length)fail(409,'Complete prerequisite tasks before marking this task done.');}if(!keys.length)fail(400,'No changes were supplied.');const s=scope(a,keys.length+2);const [updated]=await q(`UPDATE ${table} SET ${keys.map((k,i)=>`${k}=$${i+1}`).join(',')} WHERE id=$${keys.length+1} AND ${s.sql} RETURNING *`,[...keys.map(k=>k==='data'?JSON.stringify(clean[k]):clean[k]),id,...s.args]);await audit(a,table+'.updated',id,{fields:keys});await notify(r.org_id,table==='milestones'&&clean.status==='completed'&&r.status!=='completed'?'milestone_completed':table+'.updated',r.title);return updated});
 app.delete('/'+table+'/:id',async req=>{const a=await actor(req,table,true);if(!staff(a))fail(403,'Administrative access required.');const id=(req.params as {id:string}).id;await getScoped(table,id,a);const s=scope(a,2);if(['projects','leads','tickets'].includes(table))await q(`UPDATE ${table} SET status=$1 WHERE id=$2`,[table==='tickets'?'closed':'archived',id]);else await q(`DELETE FROM ${table} WHERE id=$1 AND ${s.sql}`,[id,...s.args]);await audit(a,table+'.archived',id);return {message:'Record removed from active work.'}});
